function canSplit(s: string, words: string[]): boolean {
  const dict = new Set(words);
  const maxLen = Math.max(...words.map(w => w.length));
  const n = s.length;
  const ok = new Array<boolean>(n + 1).fill(false);
  ok[0] = true; // the empty prefix
  for (let i = 1; i <= n; i++)
    for (let j = i - 1; j >= Math.max(0, i - maxLen); j--)
      if (ok[j] && dict.has(s.slice(j, i))) { ok[i] = true; break; }
  return ok[n];
}

