class Solution:
    def canSplit(self, s: str, words: List[str]) -> bool:
        dict_ = set(words)
        max_len = max(map(len, words))
        n = len(s)
        ok = [True] + [False] * n  # ok[0]: the empty prefix
        for i in range(1, n + 1):
            for j in range(i - 1, max(0, i - max_len) - 1, -1):
                if ok[j] and s[j:i] in dict_:
                    ok[i] = True
                    break
        return ok[n]

